import { delete_expense } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import trashIcon from "@/assets/trash.png";
export default {
  props: {
    custom_details: Object,
    deleteExpense: Boolean
  },
  data() {
    return {
      loading: false,
      trashIcon: trashIcon
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(delete_expense, {
          input: {
            user_email_id: data.user.user_email_id,
            category_id: this.custom_details.category_id
          }
        }));
        var response = JSON.parse(result.data.delete_expense);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          // this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
